package com.project7.localmanager;
import android.content.Context;import java.io.*;import java.util.*;import java.security.*;
/** Explicit offline trial policies. Same original Store/profile-first receipt and Progress codec. */
public final class TrialRetryGateway {
 private TrialRetryGateway(){}
 private static final String SOURCE="ce54f931f6d462d0c6fabb1f03dabf47ddc54780d89e3ec78fe21d9a6d7ef0d9",STATE="q7TrialRetry",PENDING="q7TrialRetryPending";
 private static volatile Map<Integer,Spec>catalog;
 private static final class Spec {final int scene,event,attempts;Spec(int s,int e,int a){scene=s;event=e;attempts=a;}}
 private static final class Result {int scene,remaining,win;boolean accepted;List<Integer>events=Collections.emptyList();}
 public static void prepare(Context context)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=context.getAssets().open("project7_story_missions/catalog-v1.tsv")){byte[]chunk=new byte[4096];int n;while((n=in.read(chunk))!=-1){if(bytes.size()+n>524288)throw new IOException("Trial catalog bound");bytes.write(chunk,0,n);}}String hash=hex(digest("SHA-256",bytes.toByteArray()));if(!SOURCE.equals(hash))throw new IOException("Trial source catalog changed");Map<Integer,Spec>next=new HashMap<>();for(String line:new String(bytes.toByteArray(),"UTF-8").split("\n")){String[]r=line.split("\t",-1);if(!r[0].equals("T"))continue;try{if(r.length!=7)throw new IllegalArgumentException();Spec s=new Spec(Integer.parseInt(r[1]),Integer.parseInt(r[2]),Integer.parseInt(r[6]));if(s.scene<=0||s.event<=0||s.attempts<=0||s.attempts>100||next.put(s.scene,s)!=null)throw new IllegalArgumentException();}catch(RuntimeException invalid){throw new IOException("Trial source row",invalid);}}if(next.isEmpty())throw new IOException("No trial specs");catalog=Collections.unmodifiableMap(next);}
 private static Spec spec(int scene){Map<Integer,Spec>c=catalog;return c==null?null:c.get(scene);}
 private static int integer(byte[]d,String k)throws IOException{Integer n=BsonLite.intValue(d,k);if(n==null)throw new IOException("Trial integer "+k);return n;}
 private static byte[]doc(byte[]d,String k){byte[]v=BsonLite.documentValue(d,k);return v==null?BsonLite.EMPTY_DOCUMENT:v;}
 @SuppressWarnings("unchecked")private static Set<Integer>set(Object p,String field)throws IOException{return(Set<Integer>)DreamAccess.get(p,field);}
 @SuppressWarnings("unchecked")private static Map<String,Set<Integer>>conditions(Object p)throws IOException{return(Map<String,Set<Integer>>)DreamAccess.get(p,"eventConditions");}
 private static boolean processing(Object p,Spec s)throws IOException{return set(p,"processingEvents").contains(s.event)&&!set(p,"completedEvents").contains(s.event);}
 private static boolean finite(Object graph,Spec s)throws IOException{Object outcome=((Map<?,?>)DreamAccess.get(graph,"outcomes")).get(s.event);return outcome!=null&&((Integer)DreamAccess.get(outcome,"scene"))==s.scene&&!((Set<?>)DreamAccess.get(outcome,"failure")).isEmpty();}
 private static boolean bound(Object graph,Spec s)throws IOException{Object battles=((Map<?,?>)DreamAccess.get(graph,"battles")).get(s.event);return battles instanceof Set&&((Set<?>)battles).size()==1&&((Set<?>)battles).contains(s.scene);}
 private static String week(Object p)throws IOException{Object wc=DreamAccess.get(p,"weekCommit");if(!(wc instanceof String)||((String)wc).isEmpty())throw new IOException("Trial needs authoritative week scope");return(String)wc;}
 private static int occurrence(Object p,Spec s)throws IOException{Object n=((Map<?,?>)DreamAccess.get(p,"eventCompletions")).get(s.event);return n instanceof Integer?(Integer)n:0;}
 private static boolean scoped(byte[]r,Object p,Spec s)throws IOException{if(BsonLite.stringValue(r,"source")==null)return false;return SOURCE.equals(BsonLite.stringValue(r,"source"))&&week(p).equals(BsonLite.stringValue(r,"wc"))&&Integer.valueOf(s.event).equals(BsonLite.intValue(r,"owner"))&&Integer.valueOf(occurrence(p,s)).equals(BsonLite.intValue(r,"occ"));}
 private static byte[]row(byte[]profile,Spec s){return doc(doc(profile,STATE),Integer.toString(s.scene));}
 private static byte[]ledger(byte[]profile,Spec s,byte[]r){return BsonLite.withProfileDocument(profile,STATE,BsonLite.withProfileDocument(doc(profile,STATE),Integer.toString(s.scene),r));}
 private static byte[]newRow(Object p,Spec s,boolean finite)throws IOException{boolean pending=conditions(p).getOrDefault("missionPending",Collections.emptySet()).contains(s.event)&&(!conditions(p).containsKey("missionPendingScene:"+s.event)||conditions(p).get("missionPendingScene:"+s.event).contains(s.scene));return BsonLite.document("v",1,"source",SOURCE,"wc",week(p),"owner",s.event,"occ",occurrence(p,s),"ordinal",pending?1:0,"phase",pending?"active":"ready","policy",finite?"trial-retry-total-attempts-v1":"mandatory-trial-rearm-v1");}
 private static boolean terminal(byte[]r){String phase=BsonLite.stringValue(r,"phase");return "terminal".equals(phase)||"won".equals(phase);}
 private static int budget(byte[]profile,int scene)throws IOException{Map<Integer,Integer>map=budgets(profile);return map.getOrDefault(scene,0);}
 private static Map<Integer,Integer>budgets(byte[]profile)throws IOException{Map<Integer,Integer>map=new LinkedHashMap<>();byte[]array=BsonLite.arrayValue(doc(profile,"bs"),"ab");if(array==null)return map;for(String key:BsonLite.keys(array)){byte[]pair=BsonLite.arrayValue(array,key);if(pair==null||BsonLite.keys(pair).size()!=2)throw new IOException("Original bs.ab pairs");int scene=integer(pair,"0"),n=integer(pair,"1");if(scene<=0||map.put(scene,n)!=null)throw new IOException("Original bs.ab bounds");}return map;}
 private static byte[]budget(byte[]profile,int scene,int n)throws IOException{Map<Integer,Integer>values=budgets(profile);if(n>0)values.put(scene,n);else values.remove(scene);List<List<Integer>>pairs=new ArrayList<>();for(Map.Entry<Integer,Integer>v:values.entrySet())pairs.add(Arrays.asList(v.getKey(),v.getValue()));return BsonLite.withProfileDocument(profile,"bs",BsonLite.withProfileArray(doc(profile,"bs"),"ab",pairs));}
 /** Store Service transaction calls this wrapper; no new storage owner. */
 public static void sync(LocalResourceEngine.Result result,LocalEventCatalog graph,LocalTutorialStore.Progress p){try{byte[]before=result.profile;originalSync(result,graph,p);Map<Integer,Spec>all=catalog;if(all==null||p==null)return;for(Spec s:all.values()){byte[]r=row(before,s);boolean same=scoped(r,p,s),live=processing(p,s)&&bound(graph,s);int n=0;if(same){n=terminal(r)?0:budget(before,s.scene);}else if(live){if(BsonLite.documentValue(before,PENDING)!=null)throw new IOException("Recover trial receipt before initialization");boolean fin=finite(graph,s);r=newRow(p,s,fin);result.profile=ledger(result.profile,s,r);n=fin?s.attempts:1;}else continue;final int scene=s.scene;result.replies.removeIf(reply->("setEventBattleStage".equals(reply.method)||"clearEventBattleStage".equals(reply.method)||"subEventBattleStage".equals(reply.method))&&Integer.valueOf(scene).equals(BsonLite.intValue(reply.parameters,"s")));result.profile=budget(result.profile,scene,n);result.add(n>0?"setEventBattleStage":"clearEventBattleStage",n>0?BsonLite.document("s",scene,"n",n):BsonLite.document("s",scene));}}catch(IOException e){throw new IllegalStateException("Trial service projection",e);}}
 private static void originalSync(LocalResourceEngine.Result r,LocalEventCatalog c,LocalTutorialStore.Progress p)throws IOException{Class<?>t=DreamAccess.type("LocalEventBattleEngine");try{t.getDeclaredMethod("q7OriginalSync",LocalResourceEngine.Result.class,LocalEventCatalog.class,LocalTutorialStore.Progress.class);DreamAccess.stat(t,"q7OriginalSync",new Class<?>[]{LocalResourceEngine.Result.class,LocalEventCatalog.class,LocalTutorialStore.Progress.class},r,c,p);}catch(NoSuchMethodException originalHost){DreamAccess.stat(t,"sync",new Class<?>[]{LocalResourceEngine.Result.class,LocalEventCatalog.class,LocalTutorialStore.Progress.class},r,c,p);}}
 public static void recover(LocalGatewayServer g,String account,LocalTutorialStore.Progress p,LocalEventEngine e)throws IOException{if(catalog==null||e==null||p==null)return;synchronized(e){DreamStorage.locked(g,account,tx->{recoverLocked(g,account,p,e,tx);return null;});}}
 /** Existing Week seam must call before any scope-changing Service commit. Never discard stale receipts. */
 public static void beforeScopeChange(LocalGatewayServer g,String account,LocalTutorialStore.Progress p,LocalEventEngine e)throws IOException{
  if(catalog==null||account==null)return;
  if(e!=null&&p!=null){recover(g,account,p,e);return;}
  requireNoDurableResult(g,account,null);
 }
 private static void requireNoDurableResult(LocalGatewayServer g,String account,Spec s)throws IOException{
  DreamStorage.locked(g,account,tx->{byte[]profile=tx.read();if(BsonLite.documentValue(profile,PENDING)!=null)throw new IOException("Trial recovery required before scope/null fallback");
   if(s!=null&&!BsonLite.keys(row(profile,s)).isEmpty())throw new IOException("Trial durable state requires canonical reconnect");return null;});
 }
 private static void commit(DreamStorage tx,byte[]before,byte[]next)throws IOException{try{tx.commit(before,next);}catch(RuntimeException failed){byte[]actual=tx.read();if(Arrays.equals(actual,next))return;if(Arrays.equals(actual,before))throw new IOException("Trial definite precommit rejection",failed);throw new IOException("Trial uncertain commit; reconnect",failed);}}
 private static void save(LocalGatewayServer g,String account,Object candidate)throws IOException{Object store=DreamAccess.get(g,"tutorialStore");try{DreamAccess.call(store,"save",new Class<?>[]{String.class,candidate.getClass()},account,candidate);}catch(IOException|RuntimeException failed){Object loaded=DreamAccess.call(store,"load",new Class<?>[]{String.class},account);if(!DreamProgressDelta.props(candidate).equals(DreamProgressDelta.props(loaded)))throw new IOException("Trial Progress commit not confirmed",failed);}}
 private static void recoverLocked(LocalGatewayServer g,String account,Object live,LocalEventEngine e,DreamStorage tx)throws IOException{byte[]profile=tx.read(),pending=BsonLite.documentValue(profile,PENDING);if(pending==null)return;Spec owner=spec(integer(pending,"scene"));if(owner==null||!Integer.valueOf(1).equals(BsonLite.intValue(pending,"v"))||!Integer.valueOf(owner.event).equals(BsonLite.intValue(pending,"owner"))||!SOURCE.equals(BsonLite.stringValue(pending,"source"))||!week(live).equals(BsonLite.stringValue(pending,"wc"))||!Objects.equals(BsonLite.intValue(row(profile,owner),"ordinal"),BsonLite.intValue(pending,"ordinal"))||!Objects.equals(BsonLite.stringValue(row(profile,owner),"phase"),BsonLite.stringValue(pending,"phase")))throw new IOException("Trial pending scope/owner changed");Object candidate=DreamAccess.cloneProgress(live);DreamProgressDelta.apply(candidate,doc(pending,"delta"));save(g,account,candidate);byte[]ack=BsonLite.withoutProfileKey(profile,PENDING);commit(tx,profile,ack);DreamAccess.adopt(candidate,live,e,ack);}
 private static void transition(LocalGatewayServer g,String account,Object p,LocalEventEngine e,DreamStorage tx,byte[]before,byte[]next,Object candidate,Spec owner)throws IOException{byte[]record=row(next,owner);byte[]pending=BsonLite.document("v",1,"id",UUID.randomUUID().toString(),"source",SOURCE,"wc",week(p),"scene",owner.scene,"owner",owner.event,"ordinal",integer(record,"ordinal"),"phase",BsonLite.stringValue(record,"phase"),"delta",DreamProgressDelta.capture(p,candidate));commit(tx,before,BsonLite.withProfileDocument(next,PENDING,pending));recoverLocked(g,account,p,e,tx);}
 private static byte[]initialize(byte[]profile,Object p,Object graph,Spec s)throws IOException{byte[]r=row(profile,s);if(scoped(r,p,s))return profile;if(!processing(p,s)||!bound(graph,s))return profile;boolean fin=finite(graph,s);return budget(ledger(profile,s,newRow(p,s,fin)),s.scene,fin?s.attempts:1);}
 public static boolean begin(LocalGatewayServer g,String account,LocalTutorialStore.Progress p,LocalEventEngine e,int scene)throws IOException{Spec s=spec(scene);if(s==null)return e!=null&&(Boolean)DreamAccess.call(e,"beginStoryBattle",new Class<?>[]{int.class},scene);if(e==null||p==null)return false;synchronized(e){return DreamStorage.locked(g,account,tx->{byte[]entry=tx.read();Properties entryProgress=DreamProgressDelta.props(p);try{recoverLocked(g,account,p,e,tx);byte[]before=tx.read();Object graph=DreamAccess.get(e,"catalog");byte[]profile=initialize(before,p,graph,s),r=row(profile,s);if(!processing(p,s)||!scoped(r,p,s)||terminal(r)||budget(profile,scene)<=0)return false;boolean pending=(Boolean)DreamAccess.call(e,"hasPendingStoryBattle",new Class<?>[]{int.class},scene);if(pending&&"active".equals(BsonLite.stringValue(r,"phase"))){if(!Arrays.equals(before,profile))transition(g,account,p,e,tx,before,profile,DreamAccess.cloneProgress(p),s);return true;}Object candidate=DreamAccess.cloneProgress(p);LocalEventEngine fork=DreamAccess.fork(e,candidate,profile);if(!(Boolean)DreamAccess.call(fork,"beginStoryBattle",new Class<?>[]{int.class},scene))return false;if(!owners(fork,scene).equals(Collections.singleton(s.event)))throw new IOException("Trial pending owner conflict");r=BsonLite.withProfileInt(BsonLite.withProfileString(r,"phase","active"),"ordinal",Math.addExact(integer(r,"ordinal"),1));transition(g,account,p,e,tx,before,ledger(profile,s,r),candidate,s);return true;
  }catch(IOException|RuntimeException failure){byte[]observed=tx.read();if(Arrays.equals(entry,observed)&&BsonLite.documentValue(entry,PENDING)==null&&entryProgress.equals(DreamProgressDelta.props(p)))return false;
   if(failure instanceof IOException)throw(IOException)failure;throw new IOException("Trial admission commit not confirmed; reconnect",failure);}});}}
 @SuppressWarnings("unchecked")private static Set<Integer>owners(LocalEventEngine e,int scene)throws IOException{return(Set<Integer>)DreamAccess.call(e,"pendingStoryBattleOwners",new Class<?>[]{int.class},scene);}
 public static boolean handleFinish(LocalGatewayServer g,OutputStream out,byte[]eid,byte[]params,String account,LocalTutorialStore.Progress p,LocalEventEngine e,Set<Integer>started,Set<Integer>newbees)throws IOException{Integer scene=BsonLite.intValue(params,"s");Spec s=scene==null?null:spec(scene);if(s==null||!Integer.valueOf(2).equals(BsonLite.intValue(params,"t")))return false;if(e==null||p==null){requireNoDurableResult(g,account,s);return false;}Result result=settle(g,account,p,e,s,params,false);if(result.accepted&&started!=null)started.removeAll(result.events);publish(g,out,eid,params,account,p,e,result,true,newbees);return true;}
 public static boolean handleGiveup(LocalGatewayServer g,OutputStream out,byte[]eid,byte[]params,String account,LocalTutorialStore.Progress p,LocalEventEngine e,boolean formation)throws IOException{Integer scene=BsonLite.intValue(params,"s");Spec s=scene==null?null:spec(scene);if(s==null)return false;if(e==null||p==null){requireNoDurableResult(g,account,s);return false;}Result result=settle(g,account,p,e,s,params,true);publish(g,out,eid,params,account,p,e,result,false,null);return true;}
 @SuppressWarnings("unchecked")private static Result settle(LocalGatewayServer g,String account,Object p,LocalEventEngine e,Spec s,byte[]params,boolean giveup)throws IOException{synchronized(e){return DreamStorage.locked(g,account,tx->{recoverLocked(g,account,p,e,tx);byte[]before=tx.read(),profile=initialize(before,p,DreamAccess.get(e,"catalog"),s),r=row(profile,s);Result result=new Result();result.scene=s.scene;result.remaining=budget(profile,s.scene);boolean pending=(Boolean)DreamAccess.call(e,"hasPendingStoryBattle",new Class<?>[]{int.class},s.scene);String phase=BsonLite.stringValue(r,"phase");if(terminal(r))throw new IOException("Trial durable outcome cannot identify client attempt; canonical reconnect required");if(result.remaining<=0||!scoped(r,p,s)||terminal(r)||!processing(p,s)||!bound(DreamAccess.get(e,"catalog"),s)||(!giveup&&!pending)||(!giveup&&!"active".equals(phase))||(giveup&&!"active".equals(phase)&&!"settled".equals(phase)))return result;if(pending&&!owners(e,s.scene).equals(Collections.singleton(s.event)))throw new IOException("Trial settlement owner conflict");Object candidate=DreamAccess.cloneProgress(p);LocalEventEngine fork=DreamAccess.fork(e,candidate,before);boolean fin=finite(DreamAccess.get(e,"catalog"),s);int win=giveup?0:(Integer)DreamAccess.stat(BsonLite.class,"combatWinValue",new Class<?>[]{byte[].class},params);int n=fin?Math.max(0,result.remaining-1):1;boolean terminal=giveup&&fin||!giveup&&fin&&n==0;List<Integer>completed=Collections.emptyList();
 if(win!=0){completed=(List<Integer>)DreamAccess.call(fork,"finishStoryBattle",new Class<?>[]{int.class,boolean.class},s.scene,true);n=0;r=BsonLite.withProfileString(r,"phase","won");}
 else if(terminal){if(!pending){if(!(Boolean)DreamAccess.call(fork,"beginStoryBattle",new Class<?>[]{int.class},s.scene)||!owners(fork,s.scene).equals(Collections.singleton(s.event)))throw new IOException("Trial giveup receipt owner no longer valid");}completed=(List<Integer>)DreamAccess.call(fork,giveup?"abandonStoryBattle":"finishStoryBattle",new Class<?>[]{int.class,boolean.class},s.scene,false);n=0;r=BsonLite.withProfileString(r,"phase","terminal");}
 else {if(pending&&!(Boolean)DreamAccess.call(fork,"consumeStoryScene",new Class<?>[]{int.class,int.class},s.event,s.scene))throw new IOException("Trial pending not consumed");r=BsonLite.withProfileString(r,"phase",giveup?"ready":"settled");}
 byte[]next=budget(ledger(profile,s,r),s.scene,n);transition(g,account,p,e,tx,before,next,candidate,s);result.accepted=true;result.remaining=n;result.win=win;result.events=completed;return result;});}}
 private static void publish(LocalGatewayServer g,OutputStream out,byte[]eid,byte[]params,String account,LocalTutorialStore.Progress p,LocalEventEngine e,Result result,boolean reward,Set<Integer>newbees)throws IOException{send(g,out,eid,result.remaining>0?"setEventBattleStage":"clearEventBattleStage",result.remaining>0?BsonLite.document("s",result.scene,"n",result.remaining):BsonLite.document("s",result.scene));if(!result.accepted)send(g,out,eid,"showMessageStr",BsonLite.document("m","本次试炼结算没有匹配的活动战斗，请重新进入。"));if(reward){byte[]r=(byte[])DreamAccess.stat(BsonLite.class,"combatOfflineRewardDocument",new Class<?>[]{int.class,int.class,Iterable.class,Iterable.class,int.class,byte[].class},2,result.scene,BsonLite.intArrayValues(params,"h"),BsonLite.intArrayValues(params,"x"),result.accepted?result.win:0,BsonLite.EMPTY_DOCUMENT);send(g,out,eid,"combatOfflineReward",r);}if(!result.accepted)return;for(int id:result.events){send(g,out,eid,"completeEventReplyStart",(byte[])DreamAccess.stat(BsonLite.class,"eventRewardDocument",new Class<?>[]{int.class},id));send(g,out,eid,"completeEventReplyEnd",(byte[])DreamAccess.stat(BsonLite.class,"eventDocument",new Class<?>[]{int.class},id));}DreamAccess.call(g,"syncEventEffects",new Class<?>[]{OutputStream.class,byte[].class,String.class,p.getClass(),e.getClass()},out,eid,account,p,e);if(newbees!=null&&result.win!=0)DreamAccess.call(g,"triggerPendingNewbees",new Class<?>[]{OutputStream.class,byte[].class,e.getClass(),Set.class},out,eid,e,newbees);save(g,account,p);if(result.win!=0)DreamAccess.call(g,"syncEventEffects",new Class<?>[]{OutputStream.class,byte[].class,String.class,p.getClass(),e.getClass()},out,eid,account,p,e);send(g,out,eid,"pushEvents",(byte[])DreamAccess.stat(BsonLite.class,"eventListsDocument",new Class<?>[]{Iterable.class,Iterable.class},DreamAccess.call(e,"availableEvents",new Class<?>[0]),DreamAccess.call(e,"processingEvents",new Class<?>[0])));}
 private static void send(LocalGatewayServer g,OutputStream out,byte[]eid,String method,byte[]params)throws IOException{DreamAccess.call(g,"writeFrame",new Class<?>[]{OutputStream.class,int.class,byte[].class},out,5,ProtoLite.entityMessage(eid,digest("MD5",method.getBytes("UTF-8")),params));}
 private static byte[]digest(String name,byte[]bytes){try{return MessageDigest.getInstance(name).digest(bytes);}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
 private static String hex(byte[]bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s.toString();}
}
